<header><h1 data-i="title">Creează melodie</h1><p class="hint" data-i="intro">Proiecte muzicale din voce, fredonat și propriile instrumente. Înregistrarea WAV originală rămâne sursa.</p></header>
<section class="panel" aria-labelledby="projectHeading">
<h2 id="projectHeading" data-i="project">Proiect muzical</h2>
function paintProjects(){
  $('projects').replaceChildren(...projects.map(p=>new Option(p.name,p.id)));
  if(project){$('projects').value=project.id;$('projectName').value=project.name;$('currentProject').textContent=project.name;}
  $('recovery').hidden=!dirty;$('retry').hidden=!dirty;$('recovery').textContent=t('storageError');
}
function applyUILang(){
  document.documentElement.lang=UI;document.title=t('title')+' — Scula lu Miron';
  document.querySelectorAll('[data-i]').forEach(el=>el.textContent=t(el.dataset.i));
  if(statusKey)$('status').textContent=t(statusKey,statusValue);
  paintAnalysisProgress();
  paintPack();paintState();paintProjects();paintBackup();paintJournals();quality(lastQuality);render();
}
window.addEventListener('scula-ui-lang',ev=>{UI=ev.detail==='en'?'en':'ro';applyUILang();});
/* Metadata and authoritative WAV blobs live in separate IndexedDB stores.
   Every project change and its new/deleted audio commit in one transaction. */
async function openDB(){
  const connection=await Storage.open(()=>say('storageBlocked',true));
  connection.onversionchange=()=>{connection.close();db=null;dirty=true;paintProjects();say('storageError',true);};
  return connection;
}
function read(store,key){return new Promise((resolve,reject)=>{
  if(!db)return reject(new Error('no storage'));
  const tx=db.transaction(store),r=key===undefined?tx.objectStore(store).getAll():tx.objectStore(store).get(key);
  r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);
});}
function storageFailure(error){
  dirty=true;
  if(error?.message==='writerConflict'){writable=false;conflict=true;say('writerConflict',true);}else say('storageError',true);
  paintProjects();paintState();
}
async function persist(){
  try{
    if(!writable)throw new Error('writerConflict');
    if(!db){db=await openDB();if(!await Storage.claim(db,owner))throw new Error('writerConflict');}
    revision=await Storage.commit(db,owner,revision,projects,pendingBlobs,deleted,finishedCaptures);
    pendingBlobs.clear();deleted.clear();finishedCaptures.clear();dirty=false;
    journals=await read('captures');
    coordinator?.postMessage('changed');paintJournals();
  }catch(error){storageFailure(error);}
  paintProjects();return !dirty;
}
async function coordinate(){
  if(navigator.locks){
    await new Promise(resolve=>{
      navigator.locks.request('scula-song-owner:'+owner,lock=>{
        ownerLocked=true;resolve();return new Promise(done=>{releaseLock=done;});
      }).catch(()=>resolve());
    });
  }
  const previousWriter=(await Storage.snapshot(db)).writer,previous=previousWriter.owner;
  if(ownerLocked && previousWriter.locked && previous && previous!==owner){
    // Probe the exact persisted owner, and compare it again atomically. An
    // explicit takeover may have installed another live owner in the meantime.
    writable=await navigator.locks.request('scula-song-owner:'+previous,{ifAvailable:true},lock=>Storage.claim(db,owner,!!lock,previous,ownerLocked));
  }else writable=await Storage.claim(db,owner,false,undefined,ownerLocked);
  try{coordinator=new BroadcastChannel('scula-song');coordinator.onmessage=checkWriter;}catch(_){}
    try{await Packs.installFiles(staged.pack.manifest,staged.pack.files);await refreshPack();}
    catch(_){backupSay('packStorage',null,true);return;}
  }
  // All validation and cancellation finish before the project is published.
  clearPlayers();stagedBackup=null;project=staged.project;projects.push(project);
  staged.audio.forEach((blob,key)=>pendingBlobs.set(key,blob));
  prefs.set('scula:song:project',project.id);
  $('backupJson').value='';$('backupWavs').value='';$('backupArchive').value='';backupSay('backupRestored');
  if(await persist())say('backupRestored');await render();
}
function clearPlayers(){document.querySelectorAll('.take audio').forEach(a=>{a.pause();a.removeAttribute('src');a.load();});urls.forEach(url=>URL.revokeObjectURL(url));urls.clear();}
function button(key,action){const b=document.createElement('button');if(/^(save|play|preview|audition|stop)/.test(key))b.dataset.readOnlySafe='true';b.textContent=t(key);b.type='button';b.onclick=()=>run(action);return b;}
async function render(){
  const gen=++generation;stopArrangement();clearPlayers();const host=$('recordings');host.replaceChildren();
  $('sampleSetEditor').replaceChildren();$('sampleSetPanel').hidden=true;
  renderSongTimeline();
  if(!project || !project.recordings.length){host.textContent=t('empty');return;}
  for(const r of project.recordings){
    const card=document.createElement('article');card.className='take';card.dataset.id=r.id;
    const title=document.createElement('h3');title.textContent=r.name;
    const info=document.createElement('small');info.textContent=`${t(r.purpose==='sample'?'sample':'melody')} · ${r.duration.toFixed(2)} s · ${r.sampleRate} Hz · ${r.channelCount} ch · ${r.source.encoding===3?'float':'PCM'} ${r.bitDepth} bit · ${(r.source.size/1048576).toFixed(2)} MiB`;
    card.append(title,info);
    if(r.sample){const meta=document.createElement('p');meta.textContent=Object.entries(r.sample).filter(([,v])=>v!=='' && v!==null).map(([k,v])=>t(k)+': '+v).join(' · ');card.append(meta);}
